package mk.robol.compiler.pipeline;
import java.util.ArrayList;import java.util.List;import mk.robol.compiler.ast.Ast.Program;import mk.robol.compiler.diagnostics.Diagnostic;
/** Injected compiler phases. This migration API is intentionally decoupled from the legacy UI. */
public final class CompilerPipeline {
 public interface Lexer { Output<List<Token>> lex(String source); } public interface Parser { Output<Program> parse(List<Token> tokens); } public interface SemanticAnalyzer { List<Diagnostic> analyze(Program program); } public interface CodeGenerator { String generate(Program program); }
 public static final class Output<T>{private final T value;private final List<Diagnostic> diagnostics;public Output(T v,List<Diagnostic>d){if(d==null)throw new IllegalArgumentException("Diagnostics required");value=v;diagnostics=new ArrayList<Diagnostic>(d);}public T getValue(){return value;}public List<Diagnostic> getDiagnostics(){return new ArrayList<Diagnostic>(diagnostics);}}
 private final Lexer lexer;private final Parser parser;private final SemanticAnalyzer semantic;private final CodeGenerator generator;
 public CompilerPipeline(Lexer l,Parser p,SemanticAnalyzer s,CodeGenerator g){if(l==null||p==null||s==null||g==null)throw new IllegalArgumentException("All stages are required");lexer=l;parser=p;semantic=s;generator=g;}
 public CompilationResult compile(String source){if(source==null)throw new IllegalArgumentException("Source required");List<Diagnostic>d=new ArrayList<Diagnostic>();Output<List<Token>> a=lexer.lex(source);d.addAll(a.getDiagnostics());if(errors(d)||a.getValue()==null)return new CompilationResult(null,null,d);Output<Program>b=parser.parse(a.getValue());d.addAll(b.getDiagnostics());if(errors(d)||b.getValue()==null)return new CompilationResult(b.getValue(),null,d);d.addAll(semantic.analyze(b.getValue()));if(errors(d))return new CompilationResult(b.getValue(),null,d);return new CompilationResult(b.getValue(),generator.generate(b.getValue()),d);}
 private boolean errors(List<Diagnostic>d){for(Diagnostic x:d)if(x.isError())return true;return false;}
}